export default {
  // 作用域规则配置左边树节点自定义事件扩展
  tenant_action_scope_tree_extend: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_action_scope_tree_main_wrap_left'
    },
    beforeOperate: (app, operateItem, options) => {
      if (!options.element._customRestClickFn) {
        let clickFn = options.element.bind_on_clickTreeNode //缓存当前的点击事件
        // options.element.$ds
        options.element.bind_on_clickTreeNode = async (params) => {
          const { self: vm, value } = params
          clickFn(params)
          // 其它地方有影响到节点的展示，所以需要在这里进行加个延迟处理
          setTimeout(async () => {
            const data = value.selectedData.data || {} // 获取当前的选中的树节点数据信息
            const isDimension = data.ruleType === 'DIMENSION_RULE' // 是否显示维度规则表单
            // 控制其他节点展示的ID信息
            const otherNodeIds = [
              'tree_main_wrap_right_save',
              'tree_main_wrap_right_split',
              'tree_main_wrap_right_refresh',
              'tree_table_detail'
            ]
            // 属于维度规则的ID信息
            const dimensionIds = [
              'tree_rule_from',
              'tenant_action_scope_scope_form',
              'scope_form_edit'
            ]

            otherNodeIds.forEach((id) => {
              const node = vm.$select(vm.$ds.idPre + id)
              node && (node.data.display = !isDimension)
            })
            dimensionIds.forEach((id) => {
              const node = vm.$select(vm.$ds.idPre + id) || vm.$select(id)
              node && (node.data.display = isDimension)
            })

            const editBtn = vm.$select('scope_form_edit')
            editBtn.data.value = Tech.$t('actionScope.edit')
            editBtn.$ds.isEditScopeForm = false
            vm.$select(vm.$ds.idPre + 'detail_view_title').data.value = `${
              data.name || ''
            }${Tech.$t('actionScope.ruleConfig')}`
            if (isDimension) {
              // 初始化数据信息
              const res = await window.Tech.httpMeta({
                data: {
                  // 参考元模型后端的传参规范
                  params: {
                    args: {
                      actionScopeId: data.id,
                      useDisplayForModel: true
                    },
                    context: {
                      uid: '',
                      timeZone: 'UTC+8',
                      lang: 'zh-CN'
                    },
                    model: 'tenant_action_scope',
                    tag: 'master',
                    service: 'searchActionScopeRuleRange',
                    app: 'sie-iidp-iam'
                  }
                }
              })
              const result = res.data
              const vos = result.selectedActionRuleVos || []
              const scopeFrom = vm.$select(vm.$ds.idPre + 'scope_form')
              scopeFrom.data.formConfig.disabled = true
              scopeFrom.$ds.form.actionDimensionId = result.actionDimensionId
              scopeFrom.$ds.form.selectedActionRuleVos =
                result.selectedActionRuleVos
              scopeFrom.$ds.form.selectedNames = vos
                .map((item) => item.modelDisplayName)
                .join(', ')
              // 需要数据完成填充后并且得到更新再进行清除校验信息
              setTimeout(() => {
                scopeFrom.instance.$refs.mForm.clearValidate()
              })
            }
            options.element._customRestClickFn = true // 防止重复点击
          })
        }
        return operateItem.view
      }
    }
  },
  // 新版作用域维度规则配置表单扩展
  tenant_action_scope_scope_form: {
    type: 'unshift',
    selector: {
      attr: 'id',
      value: 'tenant_action_scope_tree_rule_from_items_0'
    },
    view: {
      type: 'form', // 使用表单
      id: 'tenant_action_scope_scope_form',
      style: {
        padding: '16px'
      },
      formConfig: {
        labelPosition: 'top',
        disabled: true
      },
      dataSource: {
        showRangeDialog: false,
        isEditScopeForm: false,
        form: {
          actionDimensionId: '',
          selectedActionRuleVos: [],
          selectedNames: []
        }
      },
      items: [
        {
          type: 'lookup',
          name: 'actionDimensionId',
          mounted: (vm) => {
            if (window?.techUseMultiLang) {
              const localeLang = window?.Tech?.LANG?.locale // 当前语言
              let langData =
                window.Tech.LANG.langs[localeLang]?.['sie-snest-tenant_map']?.[
                  '*'
                ]
              if (langData) {
                vm.data.text =
                  langData.get('作用域维度') ||
                  Tech.$t('actionScope.actionDimensionTitle')
              }
            }
          },
          placeholder: Tech.$t('actionScope.actionDimensionPlaceholder'),
          text: Tech.$t('actionScope.actionDimensionTitle'),
          rules: [
            {
              required: true,
              trigger: 'change',
              message: Tech.$t('actionScope.actionDimensionId')
            }
          ],
          multiple: false,
          lookupConfig: {
            getData: async (
              dataSource = {},
              params,
              customFilter = [],
              f,
              config,
              scope
            ) => {
              // 数据域中保存列表
              let res = await window.Tech.httpMeta({
                data: {
                  // 参考元模型后端的传参规范
                  params: {
                    app: 'sie-iidp-iam',
                    model: 'tenant_action_dimension',
                    tag: 'master',
                    service: 'search',
                    args: {
                      useDisplayForModel: true,
                      filter: [['name', 'like', `%${params?.search}%`]],
                      limit: 31,
                      offset: 0,
                      order: '',
                      properties: ['id', 'name', 'modelMetaId']
                      // keyword:'' // 添加搜索参数
                    },
                    context: {
                      uid: '',
                      timeZone: 'UTC+8',
                      lang: 'zh-CN'
                    }
                  }
                }
              })

              const tmpOptions = res.data.map((item) => {
                // 拼接下拉数据，需要加上value，label属性
                return {
                  ...item,
                  value: item.id,
                  label: item.name
                }
              })
              return {
                items: tmpOptions
              }
            },
            paging: {}
          }
        },
        {
          type: 'input',
          name: 'selectedNames',
          mounted: (vm) => {
            if (window?.techUseMultiLang) {
              const localeLang = window?.Tech?.LANG?.locale // 当前语言
              let langData =
                window.Tech.LANG.langs[localeLang]?.['sie-snest-tenant_map']?.[
                  '*'
                ]
              if (langData) {
                vm.data.text =
                  langData.get('作用范围') ||
                  Tech.$t('actionScope.actionRuleTitle')
              }
            }
          },
          rules: [
            {
              required: true,
              trigger: 'change',
              message: Tech.$t('actionScope.selectedNames')
            }
          ],
          placeholder: Tech.$t('actionScope.actionRulePlaceholder'),
          text: Tech.$t('actionScope.actionRuleTitle'),
          bind_on_handleInputFocus: (params) => {
            const { self: vm, value } = params
            if (!vm.$ds.form.actionDimensionId) {
              return window.ELEMENT.Message.error(
                Tech.$t('actionScope.checkActionDimensionTips')
              )
            }
            vm.$ds.showRangeDialog = true
          }
        },
        {
          type: 'dialog',
          width: '1340px',
          title: Tech.$t('actionScope.actionRuleDialogTitle'),
          bind_display: '${$ds.showRangeDialog}',
          items: [
            {
              type: 'action-scope-select',
              id: 'tenant_action_scope_action_scope_select',
              bind_actionDimensionId: '$ds.form.actionDimensionId',
              bind_actionScopeId: '$ds.currentData.id',
              bind_selectList: '$ds.form.selectedActionRuleVos'
            }
          ],
          bind_on_opreates: async (params) => {
            const { self: vm, value } = params
            if (value.type === 'cancel') {
              vm.$ds.showRangeDialog = false
            } else if (value.type === 'confirm') {
              const selectRef = vm.$select(vm.$ds.idPre + 'action_scope_select')
              if (selectRef) {
                const { instance } = selectRef
                // 校验
                const bool = await selectRef.instance.validate()
                if (!bool) {
                  return window.ELEMENT.Message.error(
                    Tech.$t('actionScope.checkActionRuleDialogTips')
                  )
                }
                // 获取数据
                const list = instance.getData()
                vm.$ds.form.selectedNames = ''
                vm.$ds.form.selectedActionRuleVos = list
                vm.$ds.form.selectedNames = list
                  .map((item) => item.modelDisplayName)
                  .join(', ')
                vm.$ds.showRangeDialog = false
              }
            }
          }
        }
      ]
    }
  },
  // 新版作用域编辑保存按钮
  tenant_action_scope_scope_form_edit: {
    type: 'unshift',
    selector: {
      attr: 'id',
      value:
        'tenant_action_scope_tree_form_main_detail_top_header_items_0_items_1'
    },
    view: {
      type: 'button',
      id: 'scope_form_edit',
      value: '',
      style: {
        background: 'var(--button-primary-bg, #677177)',
        border: 'none',
        fontSize: '0.14rem',
        lineHeight: '0.13rem'
      },
      bind_loading: '${$ds.isSaving}',
      display: false,
      bind_on_click: async (params) => {
        const vm = params.self
        const scopeFrom = vm.$select(vm.$ds.idPre + 'scope_form')

        const lastDisabled = scopeFrom.data.formConfig.disabled
        if (vm.$ds.isEditScopeForm) {
          const data = await scopeFrom.instance.submit()
          vm.$ds.isSaving = true
          await window.Tech.httpMeta({
            data: {
              // 参考元模型后端的传参规范
              params: {
                args: {
                  saveAuthRuleRangeDto: {
                    actionDimensionId: data.actionDimensionId,
                    actionScopeId: vm.$ds.currentData.id,
                    selectedActionRuleVos: data.selectedActionRuleVos
                  },
                  useDisplayForModel: true
                },
                context: {
                  uid: '',
                  timeZone: 'UTC+8',
                  lang: 'zh-CN'
                },
                model: 'tenant_action_rule',
                tag: 'master',
                service: 'saveActionRuleRange',
                app: 'sie-iidp-iam'
              }
            }
          })
            .finally(() => {
              vm.$ds.isSaving = false
            })
            .then(() => {
              vm.$ds.isEditScopeForm = !vm.$ds.isEditScopeForm
              scopeFrom.data.formConfig.disabled = !lastDisabled
              window.ELEMENT.Message.success(Tech.$t('actionScope.saveSuccess'))
            })
        } else {
          scopeFrom.data.formConfig.disabled = !lastDisabled
          vm.$ds.isEditScopeForm = !vm.$ds.isEditScopeForm
        }

        const editBtn = vm.$select('scope_form_edit')
        editBtn.data.value = vm.$ds.isEditScopeForm
          ? Tech.$t('actionScope.save')
          : Tech.$t('actionScope.edit')
      }
    }
  },
  // 监听老版作用域规则的禁用效果
  tenant_action_scope_tree_main_wrap_right_form: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_action_scope_tree_main_wrap_right_form'
    },
    beforeOperate: (app, operate, options) => {
      options.element.created = (vm) => {
        // 监听表单数据变化信息 用来处理禁用效果
        let formNode = tech_app.page.getNode(
          vm.$ds.idPre + 'tree_main_wrap_right_form'
        )
        if (formNode) {
          let formNodeReactive = window.Tech.reactiveFn(
            formNode.data.formConfig
          )
          if (formNode.data._myWatch) {
            // 检查之前是否有对应watch 有则先销毁
            formNode.data._myWatch()
            formNode.data._myWatch = null
          }
          // 建watch
          formNode.data._myWatch = window.Tech.watchFn(
            () => formNodeReactive,
            (val) => {
              const scopeConfigForm = vm.$select('scope_config_form')
              if (scopeConfigForm) {
                scopeConfigForm.data.formConfig.disabled = val.disabled
              }
            },
            { deep: true, immediate: true }
          )
        }
      }
      options.element.destroy = () => {
        let formNode = tech_app.page.getNode(
          vm.$ds.idPre + 'tree_main_wrap_right_form'
        )
        if (formNode && formNode.data._myWatch) {
          // 检查之前是否有对应watch 有则先销毁
          formNode.data._myWatch()
          formNode.data._myWatch = null
        }
      }
    }
  },
  // 作用域维度规则信息编辑
  tenant_action_scope__dialog_form_edit_extend: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_action_scope_tree_main_wrap_left_dialog_form'
    },
    beforeOperate: (app, operate, options) => {
      options.element.created = (vm) => {
        const treeNode = vm.$select('tenant_action_scope_tree_main_wrap_left')
        if (treeNode) {
          // 当是编辑的时候，规则类型禁止修改
          if (treeNode.$ds.clickType === 'edit' && treeNode.$ds.currentId) {
            const ruleTypeNode = vm.$select(
              'tenant_action_scope_tree_main_wrap_left_dialog_form_items_0_items_ruleType'
            )
            if (ruleTypeNode) {
              ruleTypeNode.data.disabled = true
            }
          }
        }
      }
    }
  },
  // 删除作用域规则扩展
  tenant_action_scope_hook_extend_view: {
    selector: {
      attr: 'id',
      value: 'tenant_action_scope_container_main'
    },
    type: 'merge',
    hook: {
      tree: {
        afterDelete: async (vm, ...args) => {
          let userInfo = window.Tech.cookies.get('userInfo')
          await window.Tech.httpMeta({
            data: {
              // 参考元模型后端的传参规范
              params: {
                args: {
                  ids: [userInfo.id]
                },
                service: 'profile',
                model: 'rbac_user',
                app: 'sie-iidp-iam'
              }
            }
          })
          vm.data.display = false
          let tree_main_wrap_left = vm.$select(
            vm.$ds.idPre + 'tree_main_wrap_left'
          )
          vm.$ds.isEmpty = true
          vm.$cmd.initTree(tree_main_wrap_left)
          vm.$ds.currentId = null
        }
      }
    }
  }
}
