export default {
  // 作用域维度在编辑的时候 取值模型 取值字段 进行条件下禁用处理
  tenant_action_dimension_disabled_model: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_action_dimension__drawer_form_main_detail_top_common_items_0_items_modelMetaId'
    },
    beforeOperate: (app, operate, options) => {
      // 当是编辑的时候，规则类型禁止修改
      options.element.created = (vm) => {
        const row = vm.$ds.mainTableRowData
        // 当是编辑的时候，规则类型禁止修改
        if (vm.$ds.clickType === 'edit' && row.id) {
          const modelMetaIdNode = vm.$select(
            'tenant_action_dimension__drawer_form_main_detail_top_common_items_0_items_modelMetaId'
          )
          modelMetaIdNode && !row.isEdit && (modelMetaIdNode.data.disabled = true)
        }
      }
    }
  },
  // 移除作用域维度 取值模型弹窗的筛选条件配置按钮
  tenant_action_dimension_remove_search_configs_btn: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_action_dimension_menu_preform_main_table_search_configs_btn'
    },
    beforeOperate: (app, operate, options) => {
      // display: false
      options.element.display = false
    }
  },
  // 扩展作用域维度的抽屉编辑时继续禁用取值模型
  tenant_action_dimension_form_edit_btn_extend: {
    type: 'custom',
    selector: {
      attr: 'id',
      value: 'tenant_action_dimension_drawer_edit'
    },
    beforeOperate: (app, operate, options) => {
      let clickFn = options.element.bind_on_click //缓存当前的点击事件
      options.element.bind_on_click = (vm) => {
        clickFn()
        const formNode = window.vm.$select('tenant_action_dimension_form_main_detail_top_common')
        if (formNode) {
          const row = formNode.$ds.mainTableRowData
          const modelMetaIdNode = window.vm.$select(
            'tenant_action_dimension_form_main_detail_top_common_items_0_items_modelMetaId'
          )
          modelMetaIdNode && !row.isEdit && (modelMetaIdNode.data.disabled = true)
        }
      }
    }
  }
}
